proposals.refactored:
@Test
public void testConstructor() {
    assertEquals("a", new UnrecognizedOptionException("a").getMessage(),
        "Message should be 'a' when constructed with a single argument");
    assertEquals("a", new UnrecognizedOptionException("a", "b").getMessage(),
        "Message should be 'a' when constructed with option and message");
    assertEquals("b", new UnrecognizedOptionException("a", "b").getOption(),
        "Option should be 'b' when constructed with option and message");
}

